function readSetting(jsonText) {
  try {
    return JSON.parse(jsonText);
  } catch (err) {
    console.log("Invalid setting, using default.");
    return null;
  }
}

console.log(JSON.stringify(readSetting('{"volume":5}')));
console.log(JSON.stringify(readSetting('not json')));

